using GraphApi.Models.ENC.Respuestas;namespace GraphApi.Services.ENC.Respuestas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Respuestas.    /// </summary>    public interface IRespuestasService    {        /// <summary>        /// Obtiene la lista de Respuestas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadRespuestas>> GetRespuestas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Respuestas con filtros opcionales.        /// </summary>        /// <param name="respuestaID">Filtro opcional para RespuestaID.</param>        /// <param name="encuestaID">Filtro opcional para EncuestaID.</param>        /// <param name="preguntaID">Filtro opcional para PreguntaID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="opcionPreguntaID">Filtro opcional para OpcionPreguntaID.</param>        /// <param name="respuestaTexto">Filtro opcional para RespuestaTexto.</param>        /// <param name="fechaRespuesta">Filtro opcional para FechaRespuesta.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetRespuestasDynamic(            int? respuestaID,            int? encuestaID,            int? preguntaID,            int? usuarioID,            int? opcionPreguntaID,            string? respuestaTexto,            DateTime? fechaRespuesta,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Respuesta.        /// </summary>        /// <param name="objInput">Datos para crear el Respuesta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRespuestas> CreateRespuestas(            clCreateRespuestas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Respuesta.        /// </summary>        /// <param name="objInput">Datos para actualizar el Respuesta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRespuestas?> UpdateRespuestas(            clUpdateRespuestas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Respuesta por su ID.        /// </summary>        /// <param name="nRespuestasID">ID del Respuesta a eliminar.</param>        Task<bool> DeleteRespuestas(int nRespuestasID);    }}